from collections import deque

def flood_fill_from_9s(grid):
    """Flood fill 1s that are connected to 9s"""
    rows, cols = len(grid), len(grid[0])
    filled = [[False]*cols for _ in range(rows)]
    queue = deque()

    # Add all 1s adjacent to 9s
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 9:
                # Check neighbors for 1s
                for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1 and not filled[nr][nc]:
                        filled[nr][nc] = True
                        queue.append((nr, nc))

    # BFS through 1s
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1 and not filled[nr][nc]:
                filled[nr][nc] = True
                queue.append((nr, nc))

    return filled

